  config: { name: 'Pick Cv File', parameters: { jsCode: "const settings = $(\"Resolve Search Preferences\").first().json, preferred = String(settings.cvFileId || \"\").trim();\nif (preferred) return [{ json: { id: preferred, name: settings.cvFileName || \"CV importé\", mimeType: \"application/pdf\", configured: true } }];\nconst files = $input.all().map((x) => x.json).filter((f) => f && f.id && String(f.mimeType || \"\") !== \"application/vnd.google-apps.folder\");\nif (!files.length) throw new Error(\"Aucun CV dans Drive. Utilisez le formulaire pour charger un CV PDF.\");\nfiles.sort((a, b) => { const rank = (f) => String(f.mimeType || \"\") === \"application/pdf\" || String(f.name || \"\").toLowerCase().endsWith(\".pdf\") ? 0 : 1; return rank(a) - rank(b); });\nconst file = files[0];\nreturn [{ json: { id: file.id, name: file.name || \"cv\", mimeType: file.mimeType || \"\", configured: !String(settings.cvFolderId || \"\").startsWith(\"PASTE_\") } }];" }, position: [832,-160], notes: 'Keeps one readable CV: PDF first, then Google Doc or DOCX. Fails loudly when the folder is empty.', notesInFlow: true }
